// Drakan co-op: which character a partner plays (docs/journal/2026-10-31/coop-characters.md).
//
// The host plays Rynn. A joining player picks another humanoid from the roster (the NPC class 0x1009d: villagers,
// northmen, the mage ...). Nothing here touches the guest: the table lives in drakan_coop_character_table.inc
// (generated by analysis/scripts/coop_character_roster.py: ids, names and clip durations only).
//
// Why clips are mapped: no NPC model shares Rynn's skeleton, so a partner's pose (Rynn's clip ids) cannot be played on
// it directly. The ghost of a non-Rynn partner plays the character's *own* clips: every Rynn clip belongs to a coarse
// activity (idle, walk, run, attack ...), and the character has one clip per activity (with fallbacks).
//
// Character ids on the wire are the NPC class id (u16, e.g. 0x0ee7 Male Villager); 0 = Rynn (the default, no stand-in).
#pragma once
#include <cstdint>
#include <string>
#include <vector>

namespace drakan_coop_character {

// What the lobby shows for one selectable character.
struct Entry {
    uint16_t id = 0;       // wire id: NPC class id, 0 = Rynn
    uint32_t recordId = 0; // resource record id (0x50000 | class id; Rynn 0x20a50)
    std::string name;
    uint32_t modelId = 0; // model id in NPCS.MOD (3877 in SYSTEM.MOD for Rynn); a UI preview loads it from the disc
};

// Rynn first, then every NPC class that has idle, walk, run, attack and death clips (deduplicated by model: one entry
// per look). Stable order; the UI picks `id`.
const std::vector<Entry>& roster();
// Entry of `id` (the first entry, Rynn, for an unknown id).
const Entry& entry(uint16_t id);
bool known(uint16_t id);

// The local player's choice. Sent in PlayerState.character; `DRAKAN_COOP_CHARACTER=<hex class id>` presets it
// (harness).
uint16_t selected();
void setSelected(uint16_t id);

// Activities a clip is classified by (clip tables in drakan_coop_character_table.inc).
enum class Act : uint8_t {
    Idle,
    Walk,
    Run,
    RunBack,
    StrafeL,
    StrafeR,
    TurnL,
    TurnR,
    Jump,
    InAir,
    Land,
    Crouch,
    Attack,
    Hit,
    Block,
    Draw,
    Death,
    Spell,
    Roll,
    Other,
    Count
};

struct Mapped {
    uint32_t clip = 0; // resource id of the character's clip (0 = none known: keep what is playing)
    float time = 0;    // seconds into it
    Act act = Act::Other;
};
// Rynn's clip `rynnClip` (low 16 bits are enough) at `time` seconds, as played by character `id`.
Mapped mapClip(uint16_t id, uint32_t rynnClip, float time);
// Activity of a Rynn clip (Other when unknown).
Act activityOf(uint32_t rynnClip);
// A representative Rynn clip of an activity (0 = none) and its duration in seconds (test aid: DRAKAN_GHOST_ACTS).
uint32_t sampleClip(Act a, float* durationSec = nullptr);
bool actByName(const std::string& name, Act& out);

} // namespace drakan_coop_character
